import { Type, type TSchema } from "typebox";
import type { ExtensionAPI, ExtensionToolContext, ToolDefinition } from "@earendil-works/pi-coding-agent";
import { accessSync, constants, mkdirSync } from "node:fs";
import { join } from "node:path";
import type { GraphStore } from "./graph/store.js";
import { SqliteGraphStore } from "./graph/sqlite.js";
import { indexProject } from "./indexer/pipeline.js";
import { resolveMissingCallers, resolveImplementations } from "./indexer/lsp-resolver.js";
import { TsServerClient } from "./indexer/tsserver-client.js";
import { symbolGraph } from "./tools/symbol-graph.js";
import { impact } from "./tools/impact.js";
import { trace } from "./tools/trace.js";
import { resetSearchCacheForTesting as _resetSearchCache } from "./tools/symbol-search.js";
import { appendTokenMetaIfEnabled, resetSession } from "./tools/token-tracker.js";
import { suppressFreshTrustHeader, stripTrustHeader } from "./output/read-only-ceremony.js";
import { ensureHashInit } from "./output/anchoring.js";

const SymbolGraphParams = Type.Object({
  name: Type.String({ description: "Symbol name." }),
  file: Type.Optional(Type.String({ description: "Disambiguating file path." })),
  include: Type.Optional(
    Type.Array(
      Type.Union([
        Type.Literal("neighborhood"),
        Type.Literal("contract"),
        Type.Literal("source"),
      ]),
      {
        description: "Extra sections to include.",
      },
    ),
  ),
  suppressTrustHeader: Type.Optional(
    Type.Boolean({ description: "Omit the Trust header." }),
  ),
});


const ImpactParams = Type.Object({
  symbols: Type.Array(Type.String({ description: "Changed symbol." }), {
    description: "Changed symbols.",
  }),
  changeType: Type.Union(
    [
      Type.Literal("signature_change"),
      Type.Literal("removal"),
      Type.Literal("behavior_change"),
      Type.Literal("addition"),
    ],
    { description: "Change kind." },
  ),
  maxDepth: Type.Optional(
    Type.Number({ description: "Maximum traversal depth." }),
  ),
  suppressTrustHeader: Type.Optional(
    Type.Boolean({ description: "Omit the Trust header." }),
  ),
});

const TraceParams = Type.Object({
  entry: Type.String({ description: "Entry symbol or endpoint." }),
  file: Type.Optional(Type.String({ description: "Disambiguating file path." })),
  suppressTrustHeader: Type.Optional(
    Type.Boolean({ description: "Omit the Trust header." }),
  ),
});

/**
 * Machine-readable result for programmatic callers (codemode scripts). The model still receives the
 * text; scripts get the same text plus every `file  LINE:HASH` anchor already parsed out of it.
 */
const ToolOutputSchema = Type.Object({
  text: Type.String({ description: "Full model-facing output." }),
  anchors: Type.Array(
    Type.Object({
      file: Type.String(),
      line: Type.Integer(),
      hash: Type.String({ description: "3-hex hashline hash, same algorithm as pi-hashline-readmap." }),
    }),
    { description: "Editable anchors found in the output, deduplicated." },
  ),
  indexingFailed: Type.Boolean({ description: "True when the output is prefixed by an indexing-failed note." }),
});

const CODEGRAPH_NAMESPACE = {
  name: "codegraph",
  description: "Symbol-level code graph for TypeScript: callers, callees, impact, and execution paths.",
  instructions:
    "Read-only tools backed by a SQLite graph in .codegraph/graph.db that auto-indexes the project. " +
    "Outputs carry `file  LINE:HASH` anchors that are editable with pi-hashline-readmap. " +
    "structuredContent is { text, anchors, indexingFailed }.",
};

interface ProjectState {
  store: GraphStore;
  client: TsServerClient | null;
  indexing: Promise<void> | null;
  /** In-flight LSP resolutions by node id, so concurrent calls for one symbol share the work. */
  resolving: Map<string, Promise<void>>;
}

/** One entry per project root; a session can move between roots, so nothing is keyed on the first cwd. */
const projects = new Map<string, ProjectState>();
let sharedStore: GraphStore | null = null;

interface IndexErrorRecord {
  error: Error;
  setAt: number;
}

let lastIndexError: IndexErrorRecord | null = null;
type IndexProjectFn = typeof indexProject;
let indexProjectImpl: IndexProjectFn = indexProject;
export function getSharedStoreForTesting(): GraphStore | null {
  return sharedStore;
}
export function getLastIndexErrorForTesting(): Error | null {
  return lastIndexError ? lastIndexError.error : null;
}

export function setLastIndexErrorForTesting(error: Error | null, setAt: number = Date.now()): void {
  lastIndexError = error ? { error, setAt } : null;
}

export function getIndexingFailedNoteForTesting(now: number = Date.now()): string {
  if (!lastIndexError) return "";
  const ageSeconds = Math.max(0, Math.floor((now - lastIndexError.setAt) / 1000));
  return `indexing-failed (${ageSeconds}s ago): ${lastIndexError.error.message}\n`;
}

export function setIndexProjectForTesting(fn: IndexProjectFn | null): void {
  indexProjectImpl = fn ?? indexProject;
}

/** Close every store and tsserver. Idempotent: cancellation, reload and exit can all land here. */
async function closeAllProjects(): Promise<void> {
  const states = [...projects.values()];
  projects.clear();
  sharedStore = null;
  // Let an in-flight index finish briefly rather than closing the database underneath it.
  const inflight = states.map((s) => s.indexing).filter((p): p is Promise<void> => p !== null);
  if (inflight.length > 0) {
    await Promise.race([
      Promise.allSettled(inflight),
      new Promise<void>((resolve) => setTimeout(resolve, 3000).unref?.()),
    ]);
  }
  await Promise.allSettled(states.map((s) => s.client?.shutdown()));
  for (const s of states) {
    try {
      s.store.close();
    } catch {
      // already closed
    }
  }
}

export function resetStoreForTesting(): void {
  for (const s of projects.values()) {
    try {
      s.store.close();
    } catch {
      // already closed
    }
    void s.client?.shutdown().catch(() => {});
  }
  projects.clear();
  sharedStore = null;
  lastIndexError = null;
  indexProjectImpl = indexProject;
  resetSession();
  _resetSearchCache();
}

function getOrCreateProject(projectRoot: string): ProjectState {
  const existing = projects.get(projectRoot);
  if (existing) {
    sharedStore = existing.store;
    return existing;
  }
  const dbDir = join(projectRoot, ".codegraph");
  mkdirSync(dbDir, { recursive: true });
  const state: ProjectState = { store: new SqliteGraphStore(join(dbDir, "graph.db")), client: null, indexing: null, resolving: new Map() };
  projects.set(projectRoot, state);
  sharedStore = state.store;
  return state;
}

/** One tsserver per project, started lazily. It stops itself when idle and is closed on session shutdown. */
function getClient(projectRoot: string, state: ProjectState): TsServerClient {
  state.client ??= new TsServerClient(projectRoot);
  return state.client;
}

function dbIsWritable(projectRoot: string): boolean {
  const dbDir = join(projectRoot, ".codegraph");
  try {
    accessSync(join(dbDir, "graph.db"), constants.W_OK);
    accessSync(dbDir, constants.W_OK);
    return true;
  } catch {
    return false;
  }
}

function ensureIndexed(projectRoot: string, state: ProjectState): Promise<void> {
  if (state.indexing) return state.indexing;
  const run = (async () => {
    try {
      const result = await indexProjectImpl(projectRoot, state.store);
      if (result.errors > 0 && !dbIsWritable(projectRoot)) {
        lastIndexError = { error: new Error("readonly database"), setAt: Date.now() };
      } else {
        lastIndexError = null;
      }
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err));
      lastIndexError = { error, setAt: Date.now() };
    } finally {
      state.indexing = null;
    }
  })();
  state.indexing = run;
  return run;
}

function abortReason(signal: AbortSignal): Error {
  const reason = signal.reason;
  return reason instanceof Error ? reason : new Error("codegraph: operation aborted");
}

/** Reject as soon as `signal` aborts. Shared work (indexing) keeps running for other callers. */
function raceAbort<T>(work: Promise<T>, signal: AbortSignal | undefined): Promise<T> {
  if (!signal) return work;
  if (signal.aborted) return Promise.reject(abortReason(signal));
  return new Promise<T>((resolve, reject) => {
    const onAbort = () => reject(abortReason(signal));
    signal.addEventListener("abort", onAbort, { once: true });
    work.then(
      (value) => {
        signal.removeEventListener("abort", onAbort);
        resolve(value);
      },
      (error) => {
        signal.removeEventListener("abort", onAbort);
        reject(error);
      },
    );
  });
}

function setStatus(ctx: Pick<ExtensionToolContext, "hasUI" | "ui"> | undefined, text: string | undefined): void {
  try {
    if (ctx?.hasUI) ctx.ui.setStatus("codegraph", text);
  } catch {
    // status is cosmetic
  }
}

/** Resolve the project, index it if needed, and prepare hashing. Throws if `signal` aborts. */
async function prepare(ctx: ExtensionToolContext, signal: AbortSignal | undefined) {
  signal?.throwIfAborted();
  const projectRoot = ctx.cwd;
  const state = getOrCreateProject(projectRoot);
  setStatus(ctx, "codegraph: indexing…");
  try {
    await raceAbort(ensureIndexed(projectRoot, state), signal);
  } finally {
    setStatus(ctx, lastIndexError ? "codegraph: indexing failed" : undefined);
  }
  await ensureHashInit();
  return { projectRoot, state, store: state.store };
}

function indexingFailedNote(): string {
  return getIndexingFailedNoteForTesting();
}

function finalizeReadOnlyOutput(
  toolName: string,
  params: Record<string, unknown>,
  toolOutput: string,
  store: GraphStore,
  projectRoot: string,
  suppressTrustHeader: boolean = false,
): string {
  const afterFreshStrip = suppressFreshTrustHeader(toolOutput);
  const afterHeaderStrip = suppressTrustHeader ? stripTrustHeader(afterFreshStrip) : afterFreshStrip;
  // suppressTrustHeader strips only the shared Trust block; indexingFailedNote()
  // and appendTokenMetaIfEnabled() still wrap the remaining body.
  const withIndexingNote = indexingFailedNote() + afterHeaderStrip;
  if (
    lastIndexError &&
    lastIndexError.error.message !== "readonly database" &&
    afterHeaderStrip.trim().length > 0
  ) {
    lastIndexError = null;
  }
  return appendTokenMetaIfEnabled(toolName, params, withIndexingNote, store, projectRoot);
}

const ANCHOR_LINE = /^[ \t]*(\S+)[ \t]{2}(\d+):([0-9a-f]{3})\b/;

/** Pull `file  LINE:HASH` locations out of rendered output so scripts do not have to re-parse text. */
export function extractAnchors(text: string): Array<{ file: string; line: number; hash: string }> {
  const seen = new Set<string>();
  const anchors: Array<{ file: string; line: number; hash: string }> = [];
  for (const raw of text.split("\n")) {
    const match = ANCHOR_LINE.exec(raw);
    if (!match) continue;
    const key = `${match[1]}\u0000${match[2]}:${match[3]}`;
    if (seen.has(key)) continue;
    seen.add(key);
    anchors.push({ file: match[1]!, line: Number(match[2]), hash: match[3]! });
  }
  return anchors;
}

/**
 * `isError` marks a failed lookup: a requested name that does not resolve to exactly one node, the rule every
 * tool renders by. The message and its match list stay in `content` and `structuredContent`.
 */
function toolResult(output: string, isError: boolean) {
  return {
    content: [{ type: "text" as const, text: output }],
    details: undefined,
    isError,
    structuredContent: {
      text: output,
      anchors: extractAnchors(output),
      indexingFailed: output.startsWith("indexing-failed"),
    },
  };
}

type ReadOnlyToolInput<TParams extends TSchema> = Pick<
  ToolDefinition<TParams>,
  "name" | "label" | "description" | "parameters" | "execute"
> & { promptSnippet: string; promptGuidelines: string[] };

function registerReadOnlyTool<TParams extends TSchema>(pi: ExtensionAPI, tool: ReadOnlyToolInput<TParams>): void {
  const definition: ToolDefinition<TParams> = {
    ...tool,
    namespace: CODEGRAPH_NAMESPACE,
    outputSchema: ToolOutputSchema,
    // Hints for permission extensions: reads the graph, never touches the project's files or the network.
    annotations: { readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false },
    // No executionMode override: calls may run in parallel. Store writes are synchronous, indexing is
    // deduplicated per project, the tsserver client queues requests, and LSP resolution is shared per symbol.
  };
  pi.registerTool(definition);
}

function formatStatus(projectRoot: string, state: ProjectState | undefined): { text: string; level: "info" | "warning" } {
  if (!state) {
    return { text: `codegraph: ${projectRoot} is not indexed yet; it indexes on the first tool call.`, level: "info" };
  }
  const stats = state.store.getStatistics(projectRoot);
  const nodeTotal = Object.values(stats.nodes).reduce((a, b) => a + b, 0);
  const edgeTotal = Object.values(stats.edges).reduce(
    (a, byProvenance) => a + Object.values(byProvenance).reduce((x, y) => x + y, 0),
    0,
  );
  const lines = [
    `codegraph: ${projectRoot}`,
    `nodes: ${nodeTotal}  edges: ${edgeTotal}  files: ${stats.files.total} (${stats.files.stale} stale)`,
    state.indexing ? "indexing: in progress" : "indexing: idle",
  ];
  if (lastIndexError) lines.push(getIndexingFailedNoteForTesting().trimEnd());
  return { text: lines.join("\n"), level: lastIndexError ? "warning" : "info" };
}

export default function piCodegraph(pi: ExtensionAPI): void {
  // Older hosts and minimal test doubles may lack some registration methods; every one is optional.
  pi.on?.("session_start", () => {
    resetSession();
  });
  pi.on?.("session_shutdown", async () => {
    await closeAllProjects();
  });

  pi.registerCommand?.("codegraph", {
    description: "Show codegraph index status, or refresh the index (/codegraph [status|refresh])",
    handler: async (args, ctx) => {
      const sub = (args ?? "").trim().split(/\s+/)[0] || "status";
      if (sub !== "status" && sub !== "refresh") {
        ctx.ui.notify("Usage: /codegraph [status|refresh]", "warning");
        return;
      }
      if (sub === "refresh") {
        const state = getOrCreateProject(ctx.cwd);
        setStatus(ctx, "codegraph: indexing…");
        try {
          await ensureIndexed(ctx.cwd, state);
        } finally {
          setStatus(ctx, lastIndexError ? "codegraph: indexing failed" : undefined);
        }
      }
      const { text, level } = formatStatus(ctx.cwd, projects.get(ctx.cwd));
      ctx.ui.notify(text, level);
    },
  });

  registerReadOnlyTool(pi, {
    name: "symbol_graph",
    label: "Symbol Graph",
    description: "Summarize a symbol with relationships, tests, and key metadata.",
    promptSnippet: "Look up a TypeScript symbol: callers, callees, tests, contract, and anchored source",
    promptGuidelines: [
      "Use symbol_graph to find who calls or implements a symbol instead of chaining grep and read.",
      "symbol_graph anchors (`file  LINE:HASH`) are editable with the edit tool without re-reading the file.",
    ],
    parameters: SymbolGraphParams,
    async execute(_toolCallId, params, signal, _onUpdate, ctx) {
      const { projectRoot, state, store } = await prepare(ctx, signal);
      const nodes = store.findNodes(params.name, params.file);
      if (nodes.length === 1) {
        const resolvedNode = nodes[0]!;
        try {
          let shared = state.resolving.get(resolvedNode.id);
          if (!shared) {
            const client = getClient(projectRoot, state);
            shared = (async () => {
              try {
                await resolveMissingCallers(resolvedNode, store, projectRoot, client);
                if (resolvedNode.kind === "interface") {
                  await resolveImplementations(resolvedNode, store, projectRoot, client);
                }
              } finally {
                state.resolving.delete(resolvedNode.id);
              }
            })();
            state.resolving.set(resolvedNode.id, shared);
          }
          await raceAbort(shared, signal);
        } catch (error) {
          // A cancelled call must surface as cancelled, not as a quietly degraded result.
          signal?.throwIfAborted();
          void error;
          // Resolver writes failed (likely readonly DB) — continue with existing graph data.
        }
      }

      const text = symbolGraph({
        name: params.name,
        file: params.file,
        include: params.include as Array<"neighborhood" | "contract" | "source"> | undefined,
        store,
        projectRoot,
      });
      const output = finalizeReadOnlyOutput(
        "symbol_graph",
        { name: params.name, file: params.file },
        text,
        store,
        projectRoot,
        params.suppressTrustHeader === true,
      );
      return toolResult(output, nodes.length !== 1);
    },
  });


  registerReadOnlyTool(pi, {
    name: "impact",
    label: "Impact",
    description: "Classify blast radius for changed symbols.",
    promptSnippet: "Classify what breaks when TypeScript symbols change (breaking / behavioral / safe dependents)",
    promptGuidelines: [
      "Run impact on the symbols you are about to change before editing a shared function, class, or interface.",
    ],
    parameters: ImpactParams,
    async execute(_toolCallId, params, signal, _onUpdate, ctx) {
      const { projectRoot, store } = await prepare(ctx, signal);
      const text = impact({
        symbols: params.symbols,
        changeType: params.changeType,
        store,
        projectRoot,
        maxDepth: params.maxDepth,
      });
      const output = finalizeReadOnlyOutput(
        "impact",
        { symbols: params.symbols },
        text,
        store,
        projectRoot,
        params.suppressTrustHeader === true,
      );
      const failed = params.symbols.length === 0 || params.symbols.some((symbol) => store.findNodes(symbol).length !== 1);
      return toolResult(output, failed);
    },
  });

  registerReadOnlyTool(pi, {
    name: "trace",
    label: "Trace",
    description: "Return an execution path from an entry point, coverage-backed when available.",
    promptSnippet: "Trace the ordered call path from a TypeScript entry point, endpoint, or test",
    promptGuidelines: ["Use trace to follow what an entry point executes instead of reading each callee by hand."],
    parameters: TraceParams,
    async execute(_toolCallId, params, signal, _onUpdate, ctx) {
      const { projectRoot, store } = await prepare(ctx, signal);
      const text = trace({ entry: params.entry, file: params.file, store, projectRoot });
      const output = finalizeReadOnlyOutput(
        "trace",
        { entry: params.entry, file: params.file },
        text,
        store,
        projectRoot,
        params.suppressTrustHeader === true,
      );
      return toolResult(output, store.findNodes(params.entry, params.file).length !== 1);
    },
  });
}

import { readdirSync, readFileSync } from "node:fs";
import { join, relative, sep } from "node:path";

import type { GraphStore } from "../graph/store.js";
import { extractFile, sha256Hex } from "./tree-sitter.js";
import { runLspIndexStage } from "./lsp.js";
import { runAstGrepIndexStage } from "./ast-grep.js";
import { runCoverageIndexStage } from "./coverage.js";
import { runGitCoChangeStage } from "./git.js";
import { TsServerClient } from "./tsserver-client.js";
import type { ITsServerClient } from "./tsserver-client.js";

export interface IndexResult {
  indexed: number;
  skipped: number;
  removed: number;
  errors: number;
  timings: Record<string, number>;
}

export interface IndexProjectOptions {
  lspClientFactory?: (projectRoot: string) => ITsServerClient;
  coverageDir?: string;
}

function toPosixPath(p: string): string {
  return p.split(sep).join("/");
}

function walkTsFiles(root: string): string[] {
  const out: string[] = [];

  const walk = (dir: string) => {
    for (const ent of readdirSync(dir, { withFileTypes: true })) {
      if (ent.name === "node_modules" || ent.name === ".megapowers" || ent.name === ".git") continue;
      const full = join(dir, ent.name);

      if (ent.isDirectory()) {
        walk(full);
        continue;
      }

      if (ent.isFile() && (ent.name.endsWith(".ts") || ent.name.endsWith(".tsx"))) {
        out.push(full);
      }
    }
  };

  walk(root);
  return out;
}

export async function indexProject(
  projectRoot: string,
  store: GraphStore,
  options: IndexProjectOptions = {},
): Promise<IndexResult> {
  const timings: Record<string, number> = {};

  const tsStart = performance.now();
  const files = walkTsFiles(projectRoot);

  let indexed = 0;
  let skipped = 0;
  let removed = 0;
  let errors = 0;
  const changedFiles: string[] = [];

  const currentRel = new Set(files.map((absPath) => toPosixPath(relative(projectRoot, absPath))));
  for (const absPath of files) {
    const rel = toPosixPath(relative(projectRoot, absPath));
    try {
      const content = readFileSync(absPath, "utf8");
      const hash = sha256Hex(content);
      const existing = store.getFileHash(rel);
      if (existing === hash) {
        skipped++;
        continue;
      }
      if (existing !== null) {
        store.deleteFile(rel);
      }

      const extracted = extractFile(rel, content);
      store.addNode(extracted.module);
      for (const node of extracted.nodes) store.addNode(node);
      for (const edge of extracted.edges) store.addEdge(edge);
      store.setFileHash(rel, hash);
      changedFiles.push(rel);
      indexed++;
    } catch {
      errors++;
    }
  }

  for (const oldFile of store.listFiles()) {
    if (currentRel.has(oldFile) || oldFile.startsWith("__")) continue;
    try {
      store.deleteFile(oldFile);
      removed++;
    } catch {
      errors++;
    }
  }
  timings["tree-sitter"] = Math.round(performance.now() - tsStart);

  const lspStart = performance.now();
  const client = options.lspClientFactory ? options.lspClientFactory(projectRoot) : new TsServerClient(projectRoot);
  try {
    errors += await runLspIndexStage(store, projectRoot, client);
  } finally {
    await client.shutdown().catch(() => {});
  }
  timings["lsp"] = Math.round(performance.now() - lspStart);
  const astGrepStart = performance.now();
  errors += await runAstGrepIndexStage(store, projectRoot, changedFiles);
  timings["ast-grep"] = Math.round(performance.now() - astGrepStart);
  const coverageStart = performance.now();
  runCoverageIndexStage(store, projectRoot, options.coverageDir ?? join(projectRoot, ".codegraph", "coverage"));
  timings["coverage"] = Math.round(performance.now() - coverageStart);
  const gitStart = performance.now();
  errors += await runGitCoChangeStage(store, projectRoot);
  timings["git"] = Math.round(performance.now() - gitStart);

  return { indexed, skipped, removed, errors, timings };
}

// Back-compat with the existing placeholder export test
export const IndexPipeline = indexProject;

import { createHash } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import type { GraphNode } from "../graph/types.js";
import type { NeighborResult } from "../graph/store.js";
import { formatRoleTags, type NodeSignals } from "./signals.js";
import xxhashWasm from "xxhash-wasm";

const HASH_LEN = 3;
const RADIX = 16;
const HASH_MOD = RADIX ** HASH_LEN;
const HASH_DICT = Array.from({ length: HASH_MOD }, (_, i) => i.toString(RADIX).padStart(HASH_LEN, "0"));

let h32Fn: ((input: string, seed?: number) => number) | null = null;
let initPromise: Promise<void> | null = null;

export async function ensureHashInit(): Promise<void> {
  if (h32Fn) return;
  if (!initPromise) {
    initPromise = xxhashWasm().then((hasher) => {
      h32Fn = hasher.h32;
    });
  }
  await initPromise;
}

function xxh32(input: string): number {
  if (!h32Fn) throw new Error("Hash not initialized — call ensureHashInit() first");
  return h32Fn(input, 0) >>> 0;
}

export function computeLineHash(_lineNumber: number, line: string): string {
  if (line.endsWith("\r")) line = line.slice(0, -1);
  return HASH_DICT[xxh32(line) % HASH_MOD]!;
}
export interface AnchorResult {
  file: string;
  anchor: string;
  stale: boolean;
}

function sha256Hex(content: string): string {
  return createHash("sha256").update(content).digest("hex");
}

export function computeAnchor(node: GraphNode, projectRoot: string): AnchorResult {
  const fullPath = join(projectRoot, node.file);

  if (!existsSync(fullPath)) {
    return { file: node.file, anchor: `${node.start_line}:?`, stale: true };
  }

  let fileContent: string;
  try {
    fileContent = readFileSync(fullPath, "utf-8");
  } catch {
    return { file: node.file, anchor: `${node.start_line}:?`, stale: true };
  }

  const currentHash = sha256Hex(fileContent);
  const stale = currentHash !== node.content_hash;
  const lines = fileContent.split("\n");
  const lineIndex = node.start_line - 1;

  if (lineIndex < 0 || lineIndex >= lines.length) {
    return { file: node.file, anchor: `${node.start_line}:?`, stale: true };
  }

  const lineHash = computeLineHash(node.start_line, lines[lineIndex]!);
  return { file: node.file, anchor: `${node.start_line}:${lineHash}`, stale };
}

export function formatLegacyAnchorLocation(anchor: AnchorResult): string {
  if (!anchor.file) return anchor.anchor;
  const match = anchor.anchor.match(/^(\d+):([0-9a-f]{3})$/);
  if (!match) return `${anchor.file}:${anchor.anchor}`;
  return `${anchor.file}:${match[1]}:${match[2].padStart(4, "0")}`;
}

export function formatAnchorLocation(anchor: AnchorResult): string {
  return `${anchor.file}  ${anchor.anchor}`;
}

export interface RankResult {
  kept: NeighborResult[];
  omitted: number;
}

const DEFAULT_NEIGHBOR_LIMIT = 10;

export function rankNeighbors(neighbors: NeighborResult[], limit: number): RankResult {
  const effectiveLimit = limit < 0 ? DEFAULT_NEIGHBOR_LIMIT : limit;

  const sorted = [...neighbors].sort((a, b) => {
    const confidenceDiff = b.edge.provenance.confidence - a.edge.provenance.confidence;
    if (confidenceDiff !== 0) return confidenceDiff;

    return b.edge.created_at - a.edge.created_at;
  });

  const kept = sorted.slice(0, effectiveLimit);

  return {
    kept,
    omitted: sorted.length - kept.length,
  };
}

export interface AnchoredNeighbor {
  anchor: AnchorResult;
  name: string;
  edgeKind: string;
  confidence: number;
  provenanceSource: string;
  signals?: NodeSignals;
}
export interface NeighborSection {
  items: AnchoredNeighbor[];
  omitted: number;
}

export interface SymbolHeader {
  name: string;
  kind: string;
  anchor: AnchorResult;
  signals?: NodeSignals;
}
function formatSection(title: string, section: NeighborSection): string {
  if (section.items.length === 0 && section.omitted === 0) {
    return "";
  }

  const lines: string[] = [];
  lines.push(`\n### ${title}`);

  for (const item of section.items) {
    const staleMarker = item.anchor.stale ? " [stale]" : "";
    const signalTags = item.signals ? ` ${formatRoleTags(item.signals)}` : "";
    lines.push(
      `  ${formatAnchorLocation(item.anchor)}  ${item.name}  ${item.edgeKind}  confidence:${item.confidence}  ${item.provenanceSource}${staleMarker}${signalTags}`,
    );
  }

  if (section.omitted > 0) {
    lines.push(`  (${section.omitted} more omitted)`);
  }

  return lines.join("\n");
}

export interface NamedSection {
  title: string;
  section: NeighborSection;
}
export function formatNeighborhood(
  symbol: SymbolHeader,
  sections: NamedSection[],
): string {
  const staleMarker = symbol.anchor.stale ? " [stale]" : "";
  const signalTags = symbol.signals ? ` ${formatRoleTags(symbol.signals)}` : "";
  const header = `## ${symbol.name} (${symbol.kind})\n${formatAnchorLocation(symbol.anchor)}${staleMarker}${signalTags}`;
  const renderedSections = sections
    .map((s) => formatSection(s.title, s.section))
    .filter((s) => s.length > 0)
    .join("\n");
  return `${header}${renderedSections}\n`;
}

import { readFileSync } from "node:fs";
import { join } from "node:path";
import type { GraphStore } from "../graph/store.js";

interface SessionStats {
  totalCalls: number;
  totalTokensSaved: number;
}

let session: SessionStats = { totalCalls: 0, totalTokensSaved: 0 };

export function estimateNaiveCost(files: string[], projectRoot: string): number {
  let totalBytes = 0;
  for (const file of files) {
    try {
      const content = readFileSync(join(projectRoot, file), "utf8");
      totalBytes += content.length;
    } catch {
      // File missing or unreadable — skip
    }
  }
  return Math.floor(totalBytes / 4);
}

export function trackCall(_toolName: string, naiveTokens: number, actualTokens: number): void {
  session.totalCalls += 1;
  session.totalTokensSaved += Math.max(0, naiveTokens - actualTokens);
}

export function getSessionStats(): SessionStats {
  return { ...session };
}

export function resetSession(): void {
  session = { totalCalls: 0, totalTokensSaved: 0 };
}

export function formatMetaLine(_toolName: string, naiveTokens: number, actualTokens: number): string {
  trackCall(_toolName, naiveTokens, actualTokens);
  const saved = Math.max(0, naiveTokens - actualTokens);
  return `_meta: tokens_saved:${saved} naive_tokens:${naiveTokens} actual_tokens:${actualTokens} session_calls:${session.totalCalls} session_tokens_saved:${session.totalTokensSaved}`;
}

export function collectNaiveFiles(
  toolName: string,
  params: Record<string, unknown>,
  store: GraphStore,
): string[] {
  const files = new Set<string>();

  switch (toolName) {
    case "symbol_graph":
    case "symbol_card":
    case "symbol_contract": {
      const name = params.name as string | undefined;
      const file = params.file as string | undefined;
      if (!name) break;
      const nodes = store.findNodes(name, file);
      for (const node of nodes) {
        if (!node.file.startsWith("__")) files.add(node.file);
        const neighbors = store.getNeighbors(node.id);
        for (const nr of neighbors) {
          if (!nr.node.file.startsWith("__")) files.add(nr.node.file);
        }
      }
      break;
    }

    case "impact": {
      const symbols = params.symbols as string[] | undefined;
      if (!symbols) break;
      for (const sym of symbols) {
        const nodes = store.findNodes(sym);
        for (const node of nodes) {
          if (!node.file.startsWith("__")) files.add(node.file);
          const neighbors = store.getNeighbors(node.id, { direction: "in" });
          for (const nr of neighbors) {
            if (!nr.node.file.startsWith("__")) files.add(nr.node.file);
          }
        }
      }
      break;
    }

    case "trace": {
      const entry = params.entry as string | undefined;
      const file = params.file as string | undefined;
      if (!entry) break;
      const nodes = store.findNodes(entry, file);
      if (nodes.length === 1) {
        const node = nodes[0]!;
        if (!node.file.startsWith("__")) files.add(node.file);
        const seen = new Set<string>([node.id]);
        const stack = [node.id];
        while (stack.length > 0) {
          const id = stack.pop()!;
          const callees = store.getNeighbors(id, { direction: "out", kind: "calls" });
          for (const nr of callees) {
            if (!seen.has(nr.node.id)) {
              seen.add(nr.node.id);
              if (!nr.node.file.startsWith("__")) files.add(nr.node.file);
              stack.push(nr.node.id);
            }
          }
        }
      }
      break;
    }

  }

  return Array.from(files);
}

export function appendTokenMeta(
  toolName: string,
  params: Record<string, unknown>,
  toolOutput: string,
  store: GraphStore,
  projectRoot: string,
): string {
  const naiveFiles = collectNaiveFiles(toolName, params, store);
  const naiveTokens = estimateNaiveCost(naiveFiles, projectRoot);
  const actualTokens = Math.floor(toolOutput.length / 4);
  const metaLine = formatMetaLine(toolName, naiveTokens, actualTokens);
  return `${toolOutput}\n${metaLine}`;
}

export function devMetaEnabled(env: Record<string, string | undefined> = process.env): boolean {
  const raw = env.CODEGRAPH_DEVMETA?.trim().toLowerCase();
  return raw === "1" || raw === "true" || raw === "yes" || raw === "on";
}

export function appendTokenMetaIfEnabled(
  toolName: string,
  params: Record<string, unknown>,
  toolOutput: string,
  store: GraphStore,
  projectRoot: string,
): string {
  if (!devMetaEnabled()) return toolOutput;
  return appendTokenMeta(toolName, params, toolOutput, store, projectRoot);
}

import type { GraphEdge } from "../graph/types.js";
import type { GraphStore } from "../graph/store.js";
import type { ITsServerClient } from "./tsserver-client.js";

function parseEvidence(evidence: string): { name: string; line: number; col: number } | null {
  const parts = evidence.split(":");
  if (parts.length !== 3) return null;
  const [name, lineStr, colStr] = parts;
  const line = Number(lineStr);
  const col = Number(colStr);
  if (!name || !Number.isFinite(line) || !Number.isFinite(col)) return null;
  return { name, line, col };
}

function isStartupError(err: unknown): boolean {
  return err instanceof Error && err.message.startsWith("TsServer failed to start:");
}

function isUnresolvedTarget(target: string): boolean {
  return target.startsWith("__unresolved__::");
}

function makeLspEdge(source: string, target: string, evidence: string, contentHash: string): GraphEdge {
  return {
    source,
    target,
    kind: "calls",
    provenance: {
      source: "lsp",
      confidence: 0.9,
      evidence,
      content_hash: contentHash,
    },
    created_at: Date.now(),
  };
}

export async function runLspIndexStage(
  store: GraphStore,
  _projectRoot: string,
  client: ITsServerClient,
): Promise<number> {
  let errors = 0;
  const unresolved = store.getUnresolvedEdges().filter((e) => e.kind === "calls" && e.provenance.source === "tree-sitter");
  const confirmed: GraphEdge[] = [];
  for (const file of store.listFiles()) {
    for (const node of store.getNodesByFile(file)) {
      for (const e of store.getEdgesBySource(node.id)) {
        if (e.kind === "calls" && e.provenance.source === "tree-sitter" && !isUnresolvedTarget(e.target)) {
          confirmed.push(e);
        }
      }
    }
  }
  const work = [...unresolved, ...confirmed];
  for (const edge of work) {
    const sourceNode = store.getNode(edge.source);
    if (!sourceNode) continue;
    const parsed = parseEvidence(edge.provenance.evidence);
    if (!parsed) continue;
    let loc;
    try {
      loc = await client.definition(sourceNode.file, parsed.line, parsed.col);
    } catch (err) {
      if (isStartupError(err)) return errors;
      continue;
    }
    if (!loc) continue;
    if (isUnresolvedTarget(edge.target)) {
      const targetNode = store
        .getNodesByFile(loc.file)
        .find((n) => n.name === parsed.name && n.start_line === loc.line);
      if (!targetNode) continue;
      try {
        store.deleteEdge(edge.source, edge.target, edge.kind, edge.provenance.source);
        store.addEdge(makeLspEdge(edge.source, targetNode.id, `${loc.file}:${loc.line}:${loc.col}`, sourceNode.content_hash));
      } catch {
        errors++;
      }
      continue;
    }
    const existingTarget = store.getNode(edge.target);
    if (!existingTarget) continue;
    const sameTarget = existingTarget.file === loc.file && existingTarget.start_line === loc.line;
    if (!sameTarget) continue;
    try {
      store.deleteEdge(edge.source, edge.target, edge.kind, edge.provenance.source);
      store.addEdge(makeLspEdge(edge.source, edge.target, `${loc.file}:${loc.line}:${loc.col}`, sourceNode.content_hash));
    } catch {
      errors++;
    }
  }
  return errors;
}

import type { GraphStore, NeighborResult } from "../graph/store.js";
import type { GraphEdge, GraphNode } from "../graph/types.js";
import {
  computeAnchor,
  rankNeighbors,
  formatNeighborhood,
  formatAnchorLocation,
  type AnchoredNeighbor,
  type NeighborSection,
  type NamedSection,
} from "../output/anchoring.js";
import { evaluateFreshness, prependFreshnessHeader } from "../output/freshness.js";
import { createSignalComputer, type NodeSignals } from "../output/signals.js";
import { renderSymbolCardBody, renderSymbolSourceSection } from "./symbol-card.js";
import { renderSymbolContractBody } from "./symbol-contract.js";

export interface SymbolGraphParams {
  name: string;
  file?: string;
  include?: Array<"neighborhood" | "contract" | "source">;
  limit?: number;
  store: GraphStore;
  projectRoot: string;
}

export interface RenderedSymbolNeighborhood {
  body: string;
  hasLocalExceptions: boolean;
}

function isAgentEdgeStale(nr: NeighborResult, store: GraphStore): boolean {
  if (nr.edge.provenance.source !== "agent") return false;
  const sourceNode = store.getNode(nr.edge.source);
  if (!sourceNode) return true;
  const currentFileHash = store.getFileHash(sourceNode.file);
  if (!currentFileHash) return true;
  return nr.edge.provenance.content_hash !== currentFileHash;
}

function toAnchoredNeighbor(
  nr: NeighborResult,
  projectRoot: string,
  store: GraphStore,
  computeSignals?: (nodeId: string) => NodeSignals,
): AnchoredNeighbor {
  const anchor = computeAnchor(nr.node, projectRoot);
  const agentStale = isAgentEdgeStale(nr, store);
  const effectiveAnchor = agentStale ? { ...anchor, stale: true } : anchor;
  return {
    anchor: effectiveAnchor,
    name: nr.node.name,
    edgeKind: nr.edge.kind,
    confidence: nr.edge.provenance.confidence,
    provenanceSource: nr.edge.provenance.source,
    signals: computeSignals ? computeSignals(nr.node.id) : undefined,
  };
}

function buildSection(
  neighbors: NeighborResult[],
  limit: number,
  projectRoot: string,
  store: GraphStore,
  computeSignals?: (nodeId: string) => NodeSignals,
): NeighborSection {
  const ranked = rankNeighbors(neighbors, limit);
  return {
    items: ranked.kept.map((nr) => toAnchoredNeighbor(nr, projectRoot, store, computeSignals)),
    omitted: ranked.omitted,
  };
}

function hasStaleItems(section: NeighborSection): boolean {
  return section.items.some((item) => item.anchor.stale);
}

/** Map (edgeKind, direction) to a human-readable section title. */
function sectionTitle(edgeKind: string, direction: "in" | "out"): string {
  switch (edgeKind) {
    case "calls":
      return direction === "in" ? "Callers" : "Callees";
    case "imports":
      return direction === "in" ? "Imported By" : "Imports";
    case "implements":
      return direction === "in" ? "Implemented By" : "Implements";
    case "extends":
      return direction === "in" ? "Extended By" : "Extends";
    case "tested_by":
      return direction === "in" ? "Tested By" : "Tests";
    case "co_changes_with":
      return "Co-changes With";
    case "renders":
      return direction === "in" ? "Rendered By" : "Renders";
    case "routes_to":
      return direction === "in" ? "Routed From" : "Routes To";
    default: {
      const label = edgeKind.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
      return direction === "in" ? `${label} (incoming)` : `${label} (outgoing)`;
    }
  }
}

export function renderLegacyNeighborhoodBody(params: SymbolGraphParams): RenderedSymbolNeighborhood {
  const { name, file, limit = 10, store, projectRoot } = params;
  const nodes = store.findNodes(name, file);
  if (nodes.length === 0) {
    return { body: `Symbol "${name}" not found`, hasLocalExceptions: false };
  }
  if (nodes.length > 1) {
    const lines: string[] = [`Multiple matches for "${name}":\n`];
    for (const node of nodes) {
      const anchor = computeAnchor(node, projectRoot);
      const staleMarker = anchor.stale ? " [stale]" : "";
      lines.push(`  ${formatAnchorLocation(anchor)}  ${node.name} (${node.kind})${staleMarker}`);
    }
    return {
      body: `${lines.join("\n")}\n`,
      hasLocalExceptions: lines.some((line) => line.includes("[stale]")),
    };
  }
    const node = nodes[0]!;
  const symbolAnchor = computeAnchor(node, projectRoot);
  const signalComputer = createSignalComputer(store);
  const allNeighbors = store.getNeighbors(node.id);
    const computeSignals = (nodeId: string) => signalComputer.compute(nodeId);
  const buckets = new Map<string, NeighborResult[]>();
    const unresolvedResults: NeighborResult[] = [];
  for (const nr of allNeighbors) {
    if (nr.node.file.startsWith("__meta__")) continue;
    if (nr.node.file.startsWith("__unresolved__")) {
      unresolvedResults.push(nr);
      continue;
    }
      const direction = nr.edge.target === node.id ? "in" : "out";
    const title = sectionTitle(nr.edge.kind, direction);
    const bucket = buckets.get(title) ?? [];
    bucket.push(nr);
    buckets.set(title, bucket);
  }
    const sectionOrder = [
    "Callers", "Callees", "Imports", "Imported By",
    "Implemented By", "Implements",
    "Extended By", "Extends",
    "Tested By", "Tests",
    "Co-changes With",
    "Rendered By", "Renders",
    "Routed From", "Routes To",
  ];
    const namedSections: NamedSection[] = [];
  for (const title of sectionOrder) {
    const bucket = buckets.get(title);
    if (bucket && bucket.length > 0) {
      namedSections.push({ title, section: buildSection(bucket, limit, projectRoot, store, computeSignals) });
      buckets.delete(title);
    }
  }
    for (const [title, bucket] of buckets) {
    if (bucket.length > 0) {
      namedSections.push({ title, section: buildSection(bucket, limit, projectRoot, store, computeSignals) });
    }
  }
    if (unresolvedResults.length > 0) {
    namedSections.push({ title: "Unresolved", section: buildSection(unresolvedResults, limit, projectRoot, store) });
  }
  return {
    body: formatNeighborhood(
      { name: node.name, kind: node.kind, anchor: symbolAnchor, signals: signalComputer.compute(node.id) },
      namedSections,
    ),
    hasLocalExceptions: symbolAnchor.stale || namedSections.some((ns) => hasStaleItems(ns.section)),
  };
}

function collectVisibleNeighborhoodScope(params: SymbolGraphParams, node: GraphNode): {
  resultNodes: GraphNode[];
  resultEdges: GraphEdge[];
} {
  const limit = params.limit ?? 10;
  const buckets = new Map<string, NeighborResult[]>();
  const unresolvedResults: NeighborResult[] = [];

  for (const nr of params.store.getNeighbors(node.id)) {
    if (nr.node.file.startsWith("__meta__")) continue;
    if (nr.node.file.startsWith("__unresolved__")) {
      unresolvedResults.push(nr);
      continue;
    }
    const direction = nr.edge.target === node.id ? "in" : "out";
    const title = sectionTitle(nr.edge.kind, direction);
    const bucket = buckets.get(title) ?? [];
    bucket.push(nr);
    buckets.set(title, bucket);
  }

  const sectionOrder = [
    "Callers", "Callees", "Imports", "Imported By",
    "Implemented By", "Implements",
    "Extended By", "Extends",
    "Tested By", "Tests",
    "Co-changes With",
    "Rendered By", "Renders",
    "Routed From", "Routes To",
  ];
  const visible: NeighborResult[] = [];
  for (const title of sectionOrder) {
    const bucket = buckets.get(title);
    if (bucket && bucket.length > 0) {
      visible.push(...rankNeighbors(bucket, limit).kept);
      buckets.delete(title);
    }
  }
  for (const bucket of buckets.values()) visible.push(...rankNeighbors(bucket, limit).kept);
  visible.push(...rankNeighbors(unresolvedResults, limit).kept);

  return {
    resultNodes: visible
      .filter((nr) => !nr.node.file.startsWith("__unresolved__"))
      .map((nr) => nr.node),
    resultEdges: visible.map((nr) => nr.edge),
  };
}

function collectDefaultCardScope(params: SymbolGraphParams, node: GraphNode): {
  resultNodes: GraphNode[];
  resultEdges: GraphEdge[];
} {
  const allNeighbors = params.store.getNeighbors(node.id).filter(
    (nr) => !nr.node.file.startsWith("__meta__") && !nr.node.file.startsWith("__unresolved__"),
  );
  const tests = allNeighbors.filter((nr) => nr.edge.kind === "tested_by" && nr.edge.source === node.id);
  const callers = allNeighbors.filter((nr) => nr.edge.kind === "calls" && nr.edge.target === node.id).slice(0, 5);
  const callees = allNeighbors.filter((nr) => nr.edge.kind === "calls" && nr.edge.source === node.id).slice(0, 5);
  const imports = allNeighbors.filter((nr) => nr.edge.kind === "imports" && nr.edge.source === node.id).slice(0, 5);
  const extendsOut = allNeighbors.filter((nr) => nr.edge.kind === "extends" && nr.edge.source === node.id).slice(0, 5);
  const implementsOut = allNeighbors.filter((nr) => nr.edge.kind === "implements" && nr.edge.source === node.id).slice(0, 5);
  const visible = [...tests, ...callers, ...callees, ...imports, ...extendsOut, ...implementsOut];
  return {
    resultNodes: visible.map((nr) => nr.node),
    resultEdges: visible.map((nr) => nr.edge),
  };
}

function collectSymbolGraphScope(params: SymbolGraphParams): {
  targetNodes: GraphNode[];
  resultNodes: GraphNode[];
  resultEdges: GraphEdge[];
} {
  const resolvedNodes = params.store.findNodes(params.name, params.file);
  const targetNodes = resolvedNodes.length === 1 ? [resolvedNodes[0]!] : [];
  const resultNodes = new Map<string, GraphNode>();
  const resultEdges: GraphEdge[] = [];

  for (const node of resolvedNodes) resultNodes.set(node.id, node);
  if (resolvedNodes.length === 1) {
    const node = resolvedNodes[0]!;
    const scoped = (params.include ?? []).includes("neighborhood")
      ? collectVisibleNeighborhoodScope(params, node)
      : collectDefaultCardScope(params, node);
    for (const resultNode of scoped.resultNodes) resultNodes.set(resultNode.id, resultNode);
    resultEdges.push(...scoped.resultEdges);
  }

  return { targetNodes, resultNodes: [...resultNodes.values()], resultEdges };
}
export function symbolGraph(params: SymbolGraphParams): string {
  const { include } = params;
  const resolvedNodes = params.store.findNodes(params.name, params.file);
  const useNeighborhoodBase = (include ?? []).includes("neighborhood");
  const base = useNeighborhoodBase
    ? renderLegacyNeighborhoodBody(params)
    : renderSymbolCardBody({
        name: params.name,
        file: params.file,
        store: params.store,
        projectRoot: params.projectRoot,
      });
  let body = base.body;
  if (resolvedNodes.length === 1 && (include ?? []).includes("contract")) {
    const renderedContract = renderSymbolContractBody({
      name: params.name,
      file: params.file,
      store: params.store,
      projectRoot: params.projectRoot,
    });
    body = `${body}${body.endsWith("\n") ? "\n" : "\n\n"}${renderedContract.body}`;
  }

  if (resolvedNodes.length === 1 && (include ?? []).includes("source")) {
    const renderedSource = renderSymbolSourceSection({
      name: params.name,
      file: params.file,
      store: params.store,
      projectRoot: params.projectRoot,
    });
    body = `${body}${body.endsWith("\n") ? "\n" : "\n\n"}${renderedSource.body}`;
  }

  const freshness = evaluateFreshness({
    store: params.store,
    projectRoot: params.projectRoot,
    ...collectSymbolGraphScope(params),
  });
  return prependFreshnessHeader(body, freshness);
}

function stripCompactTrustHeader(lines: string[]): string | null {
  if (!lines[0]?.startsWith("Trust: ")) return null;
  let bodyStart = 1;
  while (bodyStart < lines.length && (lines[bodyStart] ?? "").startsWith("- ")) {
    bodyStart++;
  }
  return lines.slice(bodyStart).join("\n");
}

export function suppressFreshTrustHeader(text: string): string {
  const lines = text.split("\n");
  if (lines.length < 3) return text;
  if (lines[0] !== "## Trust") return text;
  if (lines[1] !== "status: fresh") return text;
  if (!(lines[2] ?? "").startsWith("evidence: ")) return text;
  return lines.slice(3).join("\n");
}

export function stripTrustHeader(text: string): string {
  const lines = text.split("\n");
  const compact = stripCompactTrustHeader(lines);
  if (compact !== null) return compact;
  if (lines.length < 3) return text;
  if (lines[0] !== "## Trust") return text;
  if (!(lines[1] ?? "").startsWith("status: ")) return text;
  if (!(lines[2] ?? "").startsWith("evidence: ")) return text;
  return lines.slice(3).join("\n");
}

