export async function runAstGrepIndexStage(
  store: GraphStore,
  projectRoot: string,
  files: string[],
  scanFn: typeof runScan = runScan,
): Promise<number> {
  let errors = 0;
  if (files.length === 0) return errors;
  const bundledDir = fileURLToPath(new URL("../rules/", import.meta.url));
  const rules = loadRules({ bundledDir, projectRoot });
  for (const rule of rules) {
    const matches = await scanFn(projectRoot, rule, files);
    errors += applyRuleMatches(store, rule, matches);
  }
  return errors;
}

export async function runGitCoChangeStage(
  store: GraphStore,
  projectRoot: string,
  options: GitCoChangeOptions = {},
): Promise<number> {
  let errors = 0;
  const head = getCurrentHead(projectRoot);
  if (!head) return errors;
  const lastHead = store.getFileHash(GIT_HEAD_KEY);
  if (lastHead === head) return errors;
  const oldEdges = store.queryRows<{ source: string; target: string }>(
    "SELECT source, target FROM edges WHERE kind = 'co_changes_with' AND provenance_source = 'git'",
  );
  for (const edge of oldEdges) {
    try {
      store.deleteEdge(edge.source, edge.target, "co_changes_with", "git");
    } catch {
      errors++;
    }
  }
  const minCount = options.minCoChangeCount ?? 2;
  const windowDays = options.windowDays ?? 365;
  const commits = parseGitLog(projectRoot);
  if (commits.length === 0) {
    try {
      store.setFileHash(GIT_HEAD_KEY, head);
    } catch {
      errors++;
    }
    return errors;
  }
  const now = Date.now();
  const halfLifeDays = windowDays / 4;
  const trackedFiles = new Set(store.listFiles());
  const pairCounts = new Map<string, { count: number; weightedScore: number }>();
  for (const commit of commits) {
    const relevantFiles = commit.files.filter((f) => trackedFiles.has(f)).sort();
    if (relevantFiles.length < 2) continue;
    const weight = computeDecayWeight(commit.dateIso, now, halfLifeDays);
    for (let i = 0; i < relevantFiles.length; i++) {
      for (let j = i + 1; j < relevantFiles.length; j++) {
        const key = `${relevantFiles[i]}|${relevantFiles[j]}`;
        const existing = pairCounts.get(key) ?? { count: 0, weightedScore: 0 };
        existing.count++;
        existing.weightedScore += weight;
        pairCounts.set(key, existing);
      }
    }
  }
  for (const [key, data] of pairCounts) {
    if (data.count < minCount) continue;
    const [fileA, fileB] = key.split("|");
    const nodeA = store.findNodes(fileA!)[0];
    const nodeB = store.findNodes(fileB!)[0];
    if (!nodeA || !nodeB) continue;
    const evidence = `co_changes: ${data.count}, recency_score: ${data.weightedScore.toFixed(1)}, window: ${windowDays}d`;
    try {
      store.addEdge({
        source: nodeA.id,
        target: nodeB.id,
        kind: "co_changes_with",
        provenance: {
          source: "git",
          confidence: Math.min(0.9, 0.3 + data.count * 0.1),
          evidence,
          content_hash: nodeA.content_hash,
        },
        created_at: Date.now(),
      });
    } catch {
      errors++;
    }
  }

  try {
    store.setFileHash(GIT_HEAD_KEY, head);
  } catch {
    errors++;
  }
  return errors;
}

export function runCoverageIndexStage(store: GraphStore, projectRoot: string, coverageDir: string): void {
  const normalized = parseCoverageReports(projectRoot, coverageDir);
  const mapped = mapCoverageToNodes(store, normalized);
  const byReport = new Map<string, MappedCoverageRecord[]>();

  for (const record of mapped) {
    const group = byReport.get(record.reportFile) ?? [];
    group.push(record);
    byReport.set(record.reportFile, group);
  }

  const reportNames = [...byReport.keys()].sort((a, b) => a.localeCompare(b));
  for (const reportFile of reportNames) {
    const group = byReport.get(reportFile)!;
    const tests = group
      .filter((record) => record.node.kind === "test" || record.file.endsWith(".test.ts") || record.file.endsWith(".spec.ts"))
      .sort((a, b) => a.node.id.localeCompare(b.node.id));
    const production = group
      .filter((record) => record.node.kind !== "test" && !record.file.endsWith(".test.ts") && !record.file.endsWith(".spec.ts"))
      .sort((a, b) => a.file.localeCompare(b.file) || a.startLine - b.startLine || a.node.id.localeCompare(b.node.id));

    for (const testRecord of tests) {
      for (const prodRecord of production) {
        store.addEdge({
          source: prodRecord.node.id,
          target: testRecord.node.id,
          kind: "tested_by",
          provenance: {
            source: "coverage",
            confidence: 1,
            evidence: `${reportFile}:${testRecord.file}:${testRecord.startLine}`,
            content_hash: prodRecord.node.content_hash,
          },
          created_at: Date.now(),
        });
      }

      const trace: TestTraceRecord = {
        testNodeId: testRecord.node.id,
        steps: [
          { nodeId: testRecord.node.id, ordinal: 0, contentHash: testRecord.node.content_hash },
          ...production.map((record, index) => ({
            nodeId: record.node.id,
            ordinal: index + 1,
            contentHash: record.node.content_hash,
          })),
        ],
      };
      store.saveTestTrace(trace);
    }
  }
  try {
    store.markCoverageIndexed();
  } catch {
    // readonly DB or other write failure: leave sentinel unset
  }
}

export async function resolveMissingCallers(
  node: GraphNode,
  store: GraphStore,
  projectRoot: string,
  client: ITsServerClient,
): Promise<void> {
  if (hasMarker(store, "callers", node)) return;

  const col = findSymbolColumn(projectRoot, node.file, node.start_line, node.name);
  let refs;
  try {
    refs = await client.references(node.file, node.start_line, col);
  } catch (err) {
    // If tsserver is permanently unavailable (not installed), set the marker so we
    // don't retry on every symbol_graph call.  For transient failures (crash, timeout,
    // etc.) leave the marker unset so the next call can succeed.
    if (err instanceof Error && err.message.startsWith("TsServer failed to start:")) {
      setMarker(store, "callers", node);
    }
    // Do NOT create edges here — writing lsp-provenance edges from a name-match
    // fallback would misrepresent confidence; the existing unresolved tree-sitter
    // edges already capture the same information honestly.
    return;
  }
  for (const ref of refs) {
    const callerNode = store
      .getNodesByFile(ref.file)
      .find((n) => n.kind !== "module" && n.start_line <= ref.line && (n.end_line === null || n.end_line >= ref.line));
    if (!callerNode) continue;
    if (callerNode.id === node.id) continue; // self reference/declaration

    const exists = store.getEdgesBySource(callerNode.id).some((e) => e.kind === "calls" && e.target === node.id);
    if (exists) continue;
    store.addEdge({
      source: callerNode.id,
      target: node.id,
      kind: "calls",
      provenance: {
        source: "lsp",
        confidence: 0.9,
        evidence: `${ref.file}:${ref.line}:${ref.col}`,
        content_hash: callerNode.content_hash,
      },
      created_at: Date.now(),
    });
  }

  setMarker(store, "callers", node);
}


